import { TrueHarness } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";

describe("ModelsClient", () => {
    test("list", async () => {
        const server = mockServerPool.createServer();
        const client = new TrueHarness({ maxRetries: 0, baseUrl: server.baseUrl });

        const rawResponseBody = { data: [{ model_id: "model_id", name: "name", properties: {} }] };

        server.mockEndpoint().get("/api/v1/models").respondWith().statusCode(200).jsonBody(rawResponseBody).build();

        const response = await client.models.list();
        expect(response).toEqual({
            data: [
                {
                    modelId: "model_id",
                    name: "name",
                    properties: {},
                },
            ],
        });
    });
});
